import{_ as n,l,o as e,c as s,v as t,p as i,x as r,d as p,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"GDP 三种算法","description":"","frontmatter":{"title":"GDP 三种算法","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/gdp-accounts.md","filePath":"econ/gdp-accounts.md","lastUpdated":1789023840000}'),A={name:"econ/gdp-accounts.md"};function E(h,a,u,_,P,B){const o=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="gdp-三种算法" tabindex="-1">GDP 三种算法 <a class="header-anchor" href="#gdp-三种算法" aria-label="Permalink to &quot;GDP 三种算法&quot;">​</a></h1><div class="epigraph"><p>国民账户不是把「幸福」加总，而是把同一年的生产、支出与收入写成三条必须对得上的账。</p><footer>—— 据联合国《国民账户体系》（SNA）；Kuznets 对国民收入的早期测算整理</footer></div><p><a href="/econ/ml-causal-econ">上一课</a>把计量收到双 debias 的 ATE。本课换尺度。宏观要的不是某一次配置的信息约束，而是已经发生的交易如何加总成「这一年的产出」。显示原理不给出总量；<a href="https://unstats.un.org/unsd/nationalaccount/" target="_blank" rel="noreferrer">SNA</a> 给出三条必须相等的算法。后课的储蓄恒等式、价格指数和增长，都默认你会这三条账，不再从「GDP 是不是福利」讲起。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>微观均衡给出的是配置与价格，不是统计局发布的那个数。若直接把所有厂商的销售收入相加，中间品会被重复计算：铁矿、钢、汽车会把同一块价值加三遍。若只加最终销售，政府服务、自有住房、存货变化又对不上企业账。缺口因此不是「要不要衡量国力」，而是：用哪一套边界，使<strong>生产、支出、收入</strong>三条路走到同一个国内生产净值概念。</p><p>SNA 把生产边界钉在市场产出，并有限度地计入政府非市场服务与部分自产。家庭内部劳动大多仍在边界外。本课只钉国内生产：常住单位在经济领土上的生产。国民总收入还要加要素的跨境净收入，那是后课经常账户才会用到的差，这里不提前展开。</p><p><span class="marginnote">GDP 是增加值之和，不是销售额之和。增加值 = 产出 − 中间消耗。存货与固定资本形成是最终支出的一部分，不是「没卖掉所以不算」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三条算法对应三本账，定义上相等，统计上用残差对平。</p><p>生产法：按产业把增加值加总，再加产品税净额。支出法：最终消费 \\(C\\)、资本形成 \\(I\\)（含存货）、政府消费 \\(G\\)、净出口 \\(NX\\)。收入法：雇员报酬、营业盈余与混合收入、生产税净额。记</p> \\[Y \\equiv C+I+G+NX, \\]<p>这里的等号是恒等，不是均衡条件。存货使「生产出来但未售出」仍计入 \\(I\\)，从而生产法与支出法在概念上对齐。收入法把同一增加值按要素份额切开；资本消耗（折旧）决定总额与净额之差。本课用总额 GDP，净额（NDP）留给资本账户。</p>',12)),(e(),i(c,null,{default:r(()=>[d(o,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20VA%5B%22%E7%94%9F%E4%BA%A7%EF%BC%9A%E5%A2%9E%E5%8A%A0%E5%80%BC%E4%B9%8B%E5%92%8C%22%5D%20--%3E%20Y%5B%22GDP%22%5D%0A%20%20EXP%5B%22%E6%94%AF%E5%87%BA%EF%BC%9AC%2BI%2BG%2BNX%22%5D%20--%3E%20Y%0A%20%20INC%5B%22%E6%94%B6%E5%85%A5%EF%BC%9A%E6%8A%A5%E9%85%AC%2B%E7%9B%88%E4%BD%99%2B%E7%94%9F%E4%BA%A7%E7%A8%8E%E5%87%80%22%5D%20--%3E%20Y%0A%20%20Y%20--%3E%20NEXT%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9AS%20%E4%B8%8E%20I%20%E7%9A%84%E6%81%92%E7%AD%89%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>名义值按当期价格；实际值要用后课的指数去缩减。本课禁止把名义 GDP 的上升直接叫「增长」。</p><h3 id="常住与领土" tabindex="-1">常住与领土 <a class="header-anchor" href="#常住与领土" aria-label="Permalink to &quot;常住与领土&quot;">​</a></h3><p>国内与国民的差，是要素收入的跨境净额。一家外资企业在境内的增加值计入 GDP；利润汇出进入 GNI 的扣减。后课开放经济会计会用到这一条；封闭核算课序里先把 \\(Y\\) 当成国内生产。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>三条路相等，是因为每一笔增加值同时是某人的收入、并对应最终需求或存货。中间品在产业间抵消：钢厂的产出是车厂的中间消耗，加总时只留下车的最终值。政府按成本计入，不是因为公共服务有市场价格，而是 SNA 选择用投入近似非市场产出——这是约定，不是福利定理。</p><p>地下经济、质量变化、免费数字服务会让边界抖动。那是测量误差，不否定恒等结构。本栏也不把 GDP 读成帕累托改进：福利定理谈的是配置，SNA 谈的是加总口径。显示原理处理的是私人信息；SNA 处理的是已经实现的市场交易。两套语言不要混：激励相容的机制可以改变未来的 \\(Y\\)，但不能让三条算法在定义上分叉。</p><p><span class="marginnote">存货投资使「没卖掉」仍进入支出法。若把存货从 \\(I\\) 里拿掉，生产法与支出法立刻对不上。后课把非自愿存货当成数量调整，前提是本课已经把它算进 \\(Y\\)。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>GDP 不含闲暇、环境耗损、分配。Kuznets 本人就警告过把国民收入当成福利。本课仍用 GDP，因为后课的索洛、IS–LM、经常账户都建立在这本账上；福利度量是对照，不是把第一课宏观改成幸福指数综述。量化栏的成交与报价是微观结构，不在 SNA 里；本栏加总到限价簿之前停住，见最后的接到<a href="/quant/lob-structure">限价簿</a>。</p><p>也不要把资本市场的市值涨跌计入生产：持有利得是重估价，不是增加值。公司金融课的股利与自由现金流从企业账出发，加总后进入收入法的盈余，但本课不把单家报表当成 GDP。</p><p>政府消费按成本计入，是 SNA 的非市场约定，不是把公共服务写成已经通过福利定理。家庭内部劳动大多在生产边界外。这些口径选择会被后课增长与开放账户继承，本课一次说清。</p><p>后课默认：写下 \\(Y\\) 时，它同时是增加值、最终支出和要素收入。下一课的缺口是：支出里的 \\(I\\) 与收入里没被消费的部分，如何写成恒等式。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>宏观的原始对象是 SNA 口径的国内生产，不是福利数字。</li><li>生产、支出、收入三条算法概念上相等；重复计算靠增加值消除。</li><li>\\(Y=C+I+G+NX\\) 是会计恒等，不是需求决定论。</li><li>存货属于资本形成；持有利得不属于生产。</li><li>名义与实际、储蓄与投资、跨境要素收入，都是后课缺口。</li><li>出处：联合国 SNA；Kuznets 的国民收入核算传统。</li></ul>',14))])}const f=n(A,[["render",E]]);export{D as __pageData,f as default};
